import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { cpus } from 'node:os';
import { join } from 'node:path';
import { planLeague } from '../apps/api/src/league/league-plan.ts';
import { reserveLeaguePartition, runLeaguePartition } from '../apps/api/src/league/league-runner.ts';
import { leagueEstimate } from '../apps/api/test-support/leagues.ts';
import { BattleBundles } from '../apps/api/src/batch/battle-bundle.ts';
import { Measurements } from '../apps/api/src/measurements.ts';
import { exportLeague } from '../apps/cli/src/league/league-export.ts';
import { localPublicationGraph } from '../apps/cli/src/publication/publication-graph.ts';
const [mode, directory, output, format] = process.argv.slice(2);
const hash = data => createHash('sha256').update(data).digest('hex');
const sha = execFileSync('git', ['rev-parse','HEAD'], {encoding:'utf8'}).trim();
if (execFileSync('git',['status','--porcelain'],{encoding:'utf8'}).trim()) throw Error('Dirty pilot source');
const source = {sha,node:process.versions.node,platform:process.platform,arch:process.arch};
const json = async p => JSON.parse(await readFile(p,'utf8'));
await mkdir(directory,{recursive:true});
if (mode === 'prepare') {
 const definition = await json('data/leagues/official-20-v2.json');
 definition.id='l5-03-pack-pilot'; definition.name='Replay pack pilot'; definition.trials=1;
 definition.characters=definition.characters.filter(c=>['guardian','fire-mage'].includes(c.id));
 if (definition.characters.length!==2||definition.battlefields.length!==5) throw Error('Changed five-field input');
 const {plan,partitions}=await planLeague(definition,source,leagueEstimate);
 if (partitions.length!==1 || partitions[0].batch.slots.length!==10) throw Error('Expected ten matches');
 const {partition,batch}=partitions[0];
 const reservation=await reserveLeaguePartition(plan,partition,[],'pack-pilot');
 const registered={source,driverSha256:hash(await readFile(new URL(import.meta.url))),lockSha256:hash(await readFile('pnpm-lock.yaml')),inputSha256:hash(JSON.stringify(definition)),cpuModel:cpus()[0]?.model,definition,plan,partitions,reservation,warmups:1,pairedTrials:5,order:['v1,v2','v2,v1','v1,v2','v2,v1','v1,v2'],scope:'One saved ten-match dataset: all five official fields, both placements, fixed inputs/seeds, reuse zero. Export and full local graph validation in separate fresh child processes. No R2, Pages, full 7600 execution or 300s claim.'};
 await writeFile(join(directory,'registered.json'),JSON.stringify(registered,null,2)+'\n');
 const result=await runLeaguePartition(plan,partition,batch,reservation,join(directory,'producer'),source,'pack-pilot',{workers:2});
 if (!result.index.complete || result.index.slots.some(s=>s.reused||s.state!=='complete')) throw Error('Pilot did not complete ten fresh results');
 await writeFile(join(directory,'result.json'),JSON.stringify(result,null,2)+'\n');
 console.log(JSON.stringify({prepared:true,source:sha,slots:result.index.slots.length}));
} else if (mode === 'trial') {
 const registered=await json(join(directory,'registered.json')), result=await json(join(directory,'result.json'));
 if (registered.source.sha!==sha) throw Error('Changed pilot source');
 const {plan,partitions,reservation}=registered;
 const completed=[{...partitions[0],reservation,result,bundles:new BattleBundles(join(directory,'producer/bundles'))}];
 const measurements=new Measurements();
 const record={source,format,driverSha256:hash(await readFile(new URL(import.meta.url))),datasetSha256:hash(JSON.stringify(result)),inputSha256:registered.inputSha256,failed:false};
 const target=output.replace(/\.json$/,'-public');
 try {
  const start=performance.now(), cpu=process.cpuUsage();
  const exported=await measurements.run(()=>exportLeague(plan,partitions,completed,target,undefined,{packs:format==='v2',verificationWorkers:2}));
  record.exportMs=performance.now()-start; record.exportCpu=process.cpuUsage(cpu);
  const audit=performance.now();
  const graph=await measurements.run(()=>localPublicationGraph(target,2));
  record.auditMs=performance.now()-audit;
  record.exported=exported; record.physicalFiles=graph.files.size; record.publicBytes=graph.totalBytes;
  record.packFiles=[...graph.files.keys()].filter(k=>k.startsWith('packs/')).length;
  record.indexFiles=[...graph.files.keys()].filter(k=>k.startsWith('pack-indexes/')).length;
  record.files=[...graph.files.values()].map(({key,bytes,checksum})=>({key,bytes,checksum}));
  record.canonicalResults=[...graph.results];
 } catch(e) {record.failed=true;record.failure=String(e); process.exitCode=1;}
 record.measurements=measurements.report(); record.maxRssKiB=process.resourceUsage().maxRSS;
 await writeFile(output,JSON.stringify(record,null,2)+'\n');
 console.log(JSON.stringify({format,failed:record.failed,exportMs:record.exportMs,auditMs:record.auditMs,files:record.physicalFiles,bytes:record.publicBytes,maxRssKiB:record.maxRssKiB}));
} else throw Error('Unknown pilot mode');

