import { readFileSync, writeFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import assert from 'node:assert/strict';
const root='.generated/pack-pilot';
const text=p=>readFileSync(p,'utf8'), read=p=>JSON.parse(text(p));
const sha=s=>createHash('sha256').update(s).digest('hex');
const registration=read(root+'/registered.json'), processes=read(root+'/process-receipts.json');
assert.equal(processes.length,12);
const dictionaries={};
const dict=value=>{const h=sha(JSON.stringify(value));dictionaries[h]??=value;return {dictionarySha256:h};};
const trials=processes.map(process=>{
 assert.equal(process.exitCode,0);
 const raw=text(process.output), result=JSON.parse(raw);
 assert.equal(result.source.sha,registration.source.sha);assert.equal(result.failed,false);
 assert.equal(result.inputSha256,registration.inputSha256);assert.equal(result.driverSha256,registration.driverSha256);
 assert.equal(result.measurements.incompleteSpans,0);assert.equal(result.measurements.droppedRecords,0);
 assert.equal(result.measurements.validation.calls,30);assert.equal(result.measurements.validation.uniqueReplays,10);
 for(const r of Object.values(result.measurements.validation.replays))assert.deepEqual(r,{calls:3,failures:0});
 assert(result.maxRssKiB*1024<1.5*1024**3);
 for(const name of ['files','canonicalResults'])result[name]=dict(result[name]);
 const restored={...result};for(const name of ['files','canonicalResults'])restored[name]=dictionaries[result[name].dictionarySha256];
 assert.equal(JSON.stringify(restored,null,2)+'\n',raw);
 return {process,rawRecordSha256:sha(raw),rawRecordBytes:Buffer.byteLength(raw),log:text(process.output.replace(/\.json$/,'.log')),result};
});
for(const f of ['v1','v2']){
 const selected=trials.filter(t=>t.result.format===f);
 assert.equal(new Set(selected.map(t=>t.result.files.dictionarySha256)).size,1);
}
assert.equal(new Set(trials.map(t=>t.result.canonicalResults.dictionarySha256)).size,1);
assert.equal(new Set(trials.map(t=>t.result.datasetSha256)).size,1);
const firstV1=trials.find(t=>t.result.format==='v1'),firstV2=trials.find(t=>t.result.format==='v2');
const originalFiles=dictionaries[firstV1.result.files.dictionarySha256].filter(f=>f.key.startsWith('objects/'));
const packedFiles=dictionaries[firstV2.result.files.dictionarySha256];
const v1Root=firstV1.process.output.replace(/\.json$/,'-public'),v2Root=firstV2.process.output.replace(/\.json$/,'-public');
const packedEntries=packedFiles.filter(f=>f.key.startsWith('pack-indexes/')).flatMap(file=>{
 const index=read(v2Root+'/'+file.key), pack=readFileSync(v2Root+'/packs/'+index.packHash.slice(7)+'.bin');
 assert.equal('sha256:'+sha(pack),index.packHash);assert.equal(pack.length,index.packBytes);
 return index.entries.map(entry=>{
  const value=pack.subarray(entry.offset,entry.offset+entry.bytes),original=readFileSync(v1Root+'/'+entry.key);
  assert(value.equals(original));assert.equal('sha256:'+sha(value),entry.checksum);
  return {key:entry.key,bytes:entry.bytes,checksum:entry.checksum};
 });
});
const ordered=files=>[...files].sort((a,b)=>a.key.localeCompare(b.key));
assert.deepEqual(ordered(packedEntries),ordered(originalFiles));
const payloadEquivalence={logicalFiles:originalFiles.length,originalPayloadBytes:originalFiles.reduce((n,f)=>n+f.bytes,0),method:'Every original v1 receipt/manifest/chunk/checkpoint is byte-for-byte equal to its v2 pack slice; whole pack, index and entry digests verified. Per-format full physical-file dictionaries are identical across all six trials.',logicalFilesSha256:sha(JSON.stringify(ordered(originalFiles)))};
const median=values=>[...values].sort((a,b)=>a-b)[Math.floor(values.length/2)];
const summary=Object.fromEntries(['v1','v2'].map(format=>{
 const selected=trials.filter(t=>t.result.format===format&&t.process.kind==='measured'),rs=selected.map(t=>t.result);
 return [format,{measuredTrials:rs.length,exportWallMedianMs:median(rs.map(r=>r.exportMs)),exportProcessCpuMedianMs:median(rs.map(r=>(r.exportCpu.user+r.exportCpu.system)/1000)),auditWallMedianMs:median(rs.map(r=>r.auditMs)),processWallMedianMs:median(selected.map(t=>t.process.processWallMs)),exportAndAuditCpuMedianMs:median(rs.map(r=>r.measurements.cpu.userMs+r.measurements.cpu.systemMs)),physicalFiles:rs[0].physicalFiles,includingOneControlObjectUpperBound:rs[0].physicalFiles+1,publicBytes:rs[0].publicBytes,packFiles:rs[0].packFiles,indexFiles:rs[0].indexFiles,maxPackBytes:Math.max(0,...dictionaries[rs[0].files.dictionarySha256].filter(f=>f.key.startsWith('packs/')).map(f=>f.bytes)),fsyncCount:rs[0].measurements.stages['save.fsync'].count,fsyncInclusiveMedianMs:median(rs.map(r=>r.measurements.stages['save.fsync'].inclusiveMs)),maxProcessRssBytes:Math.max(...rs.map(r=>r.maxRssKiB*1024)),maxInFlightPayloadBytes:Math.max(...rs.map(r=>r.measurements.capacitySampleMaxBytes['transfer.inFlightBytes']))}];
}));
const pairs=Array.from({length:5},(_,i)=>{
 const a=trials.find(t=>t.process.pair===i+1&&t.result.format==='v1').result,b=trials.find(t=>t.process.pair===i+1&&t.result.format==='v2').result;
 return {pair:i+1,exportWallDeltaMs:b.exportMs-a.exportMs,exportWallDeltaPercent:(b.exportMs/a.exportMs-1)*100};
});
const source=p=>{const contents=text(p);return {path:p,sha256:sha(contents),contents};};
const documentedRegistration=structuredClone(registration);
for (const {batch} of documentedRegistration.partitions) for (const slot of batch.slots) {
 const {key,...fields}=slot;Object.keys(slot).forEach(k=>delete slot[k]);
 Object.assign(slot,{...fields,slotIdentityDigest:'sha256:'+key});
}
const slotFieldOrder=Object.keys(registration.partitions[0].batch.slots[0]);
const restoredRegistration=structuredClone(documentedRegistration);
for (const {batch} of restoredRegistration.partitions) batch.slots=batch.slots.map(slot=>
 Object.fromEntries(slotFieldOrder.map(field=>[field,field==='key'?slot.slotIdentityDigest.slice(7):slot[field]])));
assert.equal(JSON.stringify(restoredRegistration),JSON.stringify(registration));
const report={schemaVersion:1,issue:189,phase:'L5-03',status:'bounded-local-pilot-not-full-acceptance',registration:documentedRegistration,
 registrationEncoding:{originalSha256:sha(JSON.stringify(registration)),slotFieldOrder,description:'Only report presentation changes: registration.partitions[].batch.slots[].key is stored as slotIdentityDigest with an explicit sha256: prefix. Restore the original key by removing that prefix and ordering slot fields by slotFieldOrder; compact JSON.stringify reproduces originalSha256 (asserted during report creation). Inputs and measured execution are unchanged. This prevents generic API-key scanners mistaking deterministic public slot hashes for credentials. No scanner rule or exception is changed.'},
 definition:'Same ten freshly produced saved matches; compare existing v1 export with opt-in v2 pack export on the same source. Simulation is performed once during preparation and excluded from export timing. Every trial starts a fresh Node process and empty output directory; one warmup and five alternating pairs. Full existing semantic/privacy validation: 20 calls during export, 10 during subsequent audit. No result/record expectations regenerated.',
 environment:{filesystem:'overlayfs',workers:2,payloadQueueLimitBytes:64*1024**2,payloadConcurrency:2,entryLimitBytes:16*1024**2,packTargetBytes:16*1024**2,packHardLimitBytes:32*1024**2},
 reproduction:{driver:source('.generated/pack-pilot.mjs'),runner:source('.generated/run-pack-pilot.py'),analyzer:source('.generated/summarize-pack-pilot.mjs'),commands:['git checkout '+registration.source.sha,'corepack pnpm install --frozen-lockfile','node --import ./apps/api/node_modules/tsx/dist/loader.mjs .generated/pack-pilot.mjs prepare .generated/pack-pilot','python .generated/run-pack-pilot.py','node .generated/summarize-pack-pilot.mjs'],notes:'Extract embedded sources to their paths. Use a fresh output directory. Raw trial records reconstruct by replacing files/canonicalResults references with dictionaries, preserving property order; JSON.stringify(value,null,2)+newline reproduces the recorded digest and byte count.'},
 preparation:{failedSetup:[{command:'node --import tsx .generated/pack-pilot.mjs prepare .generated/pack-pilot',exitCode:1,reason:'Root workspace cannot resolve tsx; failed before registration or computation.',log:text('.generated/pack-pilot-prepare.log')}],successfulLog:text('.generated/pack-pilot-prepare-2.log'),producerResult:read(root+'/result.json')},
 summary,payloadEquivalence,pairs,trials,dictionaries,
 interpretation:{exportMedianChangePercent:(summary.v2.exportWallMedianMs/summary.v1.exportWallMedianMs-1)*100,physicalObjectReductionPercent:(1-summary.v2.physicalFiles/summary.v1.physicalFiles)*100,byteIncreasePercent:(summary.v2.publicBytes/summary.v1.publicBytes-1)*100,conclusion:'Object count and fsync reduction are demonstrated for this fixed 10-match data. Small wall-time differences do not prove full-league speedup. Pack indexes add metadata bytes; original compressed recording and JSON bytes remain exact.',limits:['Not a 7600-match run or 270/300-second acceptance; do not extrapolate 1000-object compliance to full league.','No R2/Reader/Pages transport, Cloudflare CPU/memory or billed Class A/B request measurement; production deployment remains separate.','Local export includes full validations and durable writes; post-export audit is reported separately. Process wall additionally includes loader/startup/record writing. No cold-cache or hosted-runner claim.','Private producer remains a durable individual-bundle spool; this measures public export only. Producer fsync reduction, streaming artifact transfer and incremental finalization remain later work.','save.read ENOENT, directory.lstat ENOENT and mkdir EEXIST are expected absent/existing-path probes and retained in measurements; operation trials and all replay validations succeeded.','No pruning, budget increases, production keys or real publication used.','Recorded process CPU includes all Worker CPU; inclusive spans are not added to wall or process CPU.']}};
writeFileSync('docs/measurements/l5-03-packs.json',JSON.stringify(report,null,2)+'\n');
console.log(JSON.stringify({summary,pairs,interpretation:report.interpretation},null,2));
